/// `client.payments` 네임스페이스입니다.
class StorefrontClientPayments {
  StorefrontClientPayments._(this._http);

  final Http _http;

  /// `GET /storefront/v1/payments/{paymentId}` — 결제 상태 조회. 복귀 화면에서 결과가 확인 중(`processing`)이면
  /// `expiresAt`까지 폴링합니다. `completed`면 `orderId`로 완료 화면, `failed`·`expired`면 실패 안내입니다.
  /// TTL이 지난 `pending`은 `expired`로 보고됩니다. `testPayment`는 완료면 주문 플래그, 아니면 세션 환경입니다.
  ///
  /// 에러: 404 `PAYMENT_NOT_FOUND`(없음·다른 상점) · 410 `STORE_CLOSED` · 503 `STORE_SUSPENDED`.
  Future<PaymentStatus> getStatus(String paymentId) async =>
      _http.request('GET', '/payments/${encodeURIComponent('$paymentId')}', paymentStatusSchema);

  /// `POST /payments/{paymentId}/attempts` — 같은 결제에서 다른 결제 옵션으로 다시 시도합니다. 새 시도의 결제창 값을
  /// 돌려줍니다. 승인 중이거나 결과 확인 중이면 409 `PAYMENT_IN_PROGRESS`입니다.
  Future<PaymentStart> retry(String paymentId, RetryPaymentRequest body) async => _http.request(
      'POST',
      '/payments/${encodeURIComponent('$paymentId')}/attempts',
      paymentStartSchema,
      RequestOptions(body: retryPaymentRequestSchema.parse(body).toJson()));

  /// `POST /payments/{paymentId}/confirm` — PG 결제창이 돌려준 승인 키로 결제를 승인하고 주문을 만듭니다(복귀 화면).
  /// 같은 승인 키의 재호출은 저장된 결과를 돌려줍니다(멱등).
  ///
  /// 에러: 403 `CALLBACK_TOKEN_INVALID` · 400 `AMOUNT_MISMATCH` · 402 `PAYMENT_DECLINED` · 409 `ATTEMPT_NOT_CURRENT`·`PAYMENT_IN_PROGRESS`·
  /// `ALREADY_PROCESSED` · 409 `ATTEMPT_CAPTURED`(`details.pgTransactionId`로 다시 승인).
  Future<PaymentConfirmResult> confirm(String paymentId, ConfirmPaymentRequest body) async => _http.request(
      'POST',
      '/payments/${encodeURIComponent('$paymentId')}/confirm',
      paymentConfirmResultSchema,
      RequestOptions(body: confirmPaymentRequestSchema.parse(body).toJson()));

  /// `POST /payments/{paymentId}/failure` — 결제창 실패(준비 장애·거절·구매자 취소)를 보고합니다. 서버가 PG 기록으로 확인한 뒤
  /// 시도를 닫고, 그 뒤 같은 결제를 다른 옵션으로 `retry`할 수 있습니다. PG에서 이미 매입됐으면 409 `ATTEMPT_CAPTURED`
  /// (`details.pgTransactionId`로 승인합니다), 확인할 수 없으면 409 `ATTEMPT_RESULT_PENDING`·503 `PG_LOOKUP_UNAVAILABLE`입니다.
  Future<PaymentFailureResult> reportFailure(String paymentId, ReportPaymentFailureRequest body) async => _http.request(
      'POST',
      '/payments/${encodeURIComponent('$paymentId')}/failure',
      paymentFailureResultSchema,
      RequestOptions(body: reportPaymentFailureRequestSchema.parse(body).toJson()));
}

/// `client.myOrders` 네임스페이스입니다.
