  /// 429 `TOO_MANY_REQUESTS`(주문번호마다 10분에 5번까지 확인하고, 5번째가 틀리면 30분 잠금.
  /// 주문번호마다 하루 15번, 상점 전체 분당 한도도 있습니다. 남은 시간은 `ApiError.details.retryAfterSeconds`).
  /// 맞게 조회하면 주문번호의 횟수가 초기화됩니다. 본문 형식은 `guestInfoSchema`의 `phone`·`orderPassword`와 같습니다.
  /// 429는 연락처·비밀번호가 맞아도 납니다 — 「잠시 후 다시 시도」로 안내합니다.
  ///
  /// `POST /storefront/v1/guest/orders/{orderId}`
  Future<MyOrder> getGuestOrder(String orderId, {required String phone, required String orderPassword}) async =>
      _http.request('POST', '/guest/orders/${encodeURIComponent('$orderId')}', myOrderSchema,
          RequestOptions(body: compact({'phone': phone, 'orderPassword': orderPassword})));

  /// `GET /storefront/v1/me/order-items/{orderItemId}/delivery`
  Future<DeliveryTracking> getDelivery(String orderItemId) async =>
      _http.request('GET', '/me/order-items/${encodeURIComponent('$orderItemId')}/delivery', deliveryTrackingSchema);

  /// `POST /storefront/v1/me/order-items/{orderItemId}/purchase-decision`
  Future<void> decidePurchase(String orderItemId) async =>
      _http.requestVoid('POST', '/me/order-items/${encodeURIComponent('$orderItemId')}/purchase-decision');

  /// `POST /me/order-items/{id}/actions/{key}` — 주문상품 `actions`에 켜진 행동을 실행합니다(#115, 시안 승인 등).
  /// 응답의 `flowState`·`actions`로 화면을 바로 바꿉니다. 에러: 409 `ACTION_NOT_AVAILABLE`(`details.reason`).
  ///
  /// `POST /storefront/v1/me/order-items/{orderItemId}/actions/{key}`
  Future<FlowActionResult> act(String orderItemId, String key, [Map<String, Object?> input = const {}]) async =>
      _http.request(
          'POST',
          '/me/order-items/${encodeURIComponent('$orderItemId')}/actions/${encodeURIComponent('$key')}',
          flowActionResultSchema,
          RequestOptions(body: flowActionRequestSchema.parse({'input': input}).toJson()));

  /// 비회원 행동 — 비회원 주문 조회와 같은 연락처·비밀번호 확인과 시도 한도를 지납니다.
