  /// 주문상품별로 줍니다(부분 실행). 켜진 주문상품이 하나도 없으면 409 `ACTION_NOT_AVAILABLE`.
  ///
  /// `POST /storefront/v1/me/orders/{orderId}/actions/{key}`
  Future<OrderFlowActionResult> actOnOrder(String orderId, String key, [Map<String, Object?> input = const {}]) async =>
      _http.request('POST', '/me/orders/${encodeURIComponent('$orderId')}/actions/${encodeURIComponent('$key')}',
          orderFlowActionResultSchema, RequestOptions(body: flowActionRequestSchema.parse({'input': input}).toJson()));

  /// 비회원 주문 전체 행동 — 비회원 주문 조회와 같은 확인·시도 한도.
  ///
  /// `POST /storefront/v1/guest/orders/{orderId}/actions/{key}`
  Future<OrderFlowActionResult> guestActOnOrder(String orderId, String key,
          {required String phone, required String orderPassword, Map<String, Object?>? input}) async =>
      _http.request(
          'POST',
          '/guest/orders/${encodeURIComponent('$orderId')}/actions/${encodeURIComponent('$key')}',
          orderFlowActionResultSchema,
          RequestOptions(
              body: guestFlowActionRequestSchema
                  .parse(compact({'phone': phone, 'orderPassword': orderPassword, 'input': input}))
                  .toJson()));
}

