  final StorefrontClientMeCustomerInquiries customerInquiries;

  /// `GET /me/coupons` — 내 쿠폰(이슈 #47). `status`로 사용 가능·사용함·기간 지남을 거릅니다.
  Future<List<MyCoupon>> coupons({String? status}) async => _http.request(
      'GET', '/me/coupons', z.array<MyCoupon>(myCouponSchema), RequestOptions(query: compact({'status': status})));

  /// `POST /coupons/{couponId}/download` — 쿠폰 받기(이슈 #110, 회원 전용). 받은 쿠폰 한 장(내 쿠폰 항목)을 돌려줍니다.
  ///
  /// 에러(`ApiError.code`): 401 `UNAUTHORIZED`, 404 `COUPON_NOT_FOUND`(없음·중지·종료·다운로드 쿠폰 아님),
  /// 409 `COUPON_ALREADY_DOWNLOADED`(1인 장수를 다 받음)·`COUPON_SOLD_OUT`(총 발급 한도 소진)·`COUPON_NOT_STARTED`·
  /// `COUPON_EXPIRED`, 429 `TOO_MANY_REQUESTS`.
  Future<MyCoupon> downloadCoupon(String couponId) async =>
      _http.request('POST', '/coupons/${encodeURIComponent('$couponId')}/download', myCouponSchema);
}
